    delete h.art;
    const r = RATING[key] || [5, 5, 5, 5];
    h.rating = { basic: r[0], durability: r[1], ability: r[2], mobility: r[3] };
    (LEGACY_FLEX[key] || []).forEach(role => {
      if (!h.roles.includes(role) && !h.flex.some(f => f.r === role)) h.flex.push({ r: role, src: 'Z původní databáze – zatím bez oficiálního potvrzení', legacy: true });
    });
    h.banner = BANNER[h.n] ? CF + BANNER[h.n] : null;
